import grpc
from concurrent import futures
import os
import re
import unicodedata

# Generated protobuf stubs
import user_service_pb2
import user_service_pb2_pb2_grpc

DATA_DIR = "/app/data/users"

def normalize_username(username):
    """Normalize unicode characters in username for consistent storage."""
    # NFKC normalization - maps compatibility characters to canonical forms
    normalized = unicodedata.normalize('NFKC', username)
    return normalized

def sanitize_path_component(component):
    """Basic sanitization - remove obvious traversal attempts."""
    # Block literal '../' sequences
    if '../' in component or '..\\' in component:
        raise ValueError("Path traversal detected")
    # Block null bytes
    if '\x00' in component:
        raise ValueError("Null byte detected")
    # Only allow alphanumeric, dash, underscore, dot
    if not re.match(r'^[\w.\-]+$', component):
        raise ValueError("Invalid characters in username")
    return component

class UserServiceServicer(user_service_pb2_pb2_grpc.UserServiceServicer):

    def GetUserProfile(self, request, context):
        """Retrieve user profile data from filesystem."""
        username = request.username

        # Step 1: Sanitize BEFORE normalization (vulnerability!)
        try:
            safe_name = sanitize_path_component(username)
        except ValueError as e:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details(str(e))
            return user_service_pb2.UserProfileResponse()

        # Step 2: Normalize AFTER sanitization
        # Unicode normalization can reintroduce dangerous sequences
        # e.g., U+FF0E (fullwidth full stop) normalizes to U+002E (.)
        # e.g., U+2025 (two dot leader) normalizes to U+002E U+002E (..)
        normalized_name = normalize_username(safe_name)

        # Step 3: Construct file path with post-normalization string
        filepath = os.path.join(DATA_DIR, normalized_name + ".json")

        try:
            with open(filepath, 'r') as f:
                profile_data = f.read()
            return user_service_pb2.UserProfileResponse(
                profile_json=profile_data,
                status="ok"
            )
        except FileNotFoundError:
            context.set_code(grpc.StatusCode.NOT_FOUND)
            context.set_details(f"Profile not found for user: {normalized_name}")
            return user_service_pb2.UserProfileResponse()
        except PermissionError:
            context.set_code(grpc.StatusCode.PERMISSION_DENIED)
            context.set_details("Access denied")
            return user_service_pb2.UserProfileResponse()

    def UpdateUserProfile(self, request, context):
        """Update user profile - writes to filesystem."""
        username = request.username

        try:
            safe_name = sanitize_path_component(username)
        except ValueError as e:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details(str(e))
            return user_service_pb2.UpdateResponse()

        normalized_name = normalize_username(safe_name)
        filepath = os.path.join(DATA_DIR, normalized_name + ".json")

        try:
            with open(filepath, 'w') as f:
                f.write(request.profile_json)
            return user_service_pb2.UpdateResponse(success=True)
        except Exception as e:
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details(f"Write failed: {str(e)}")
            return user_service_pb2.UpdateResponse(success=False)

def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    user_service_pb2_pb2_grpc.add_UserServiceServicer_to_server(
        UserServiceServicer(), server
    )
    port = os.environ.get('GRPC_PORT', '50051')
    server.add_insecure_port(f'[::]:{port}')
    server.start()
    print(f"gRPC UserService listening on port {port}")
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
